# exercise: ch04
# expected:
# Bash(git status) -> allow
# Bash(rm -rf /) -> deny
# Bash(npm test) -> ask
RULES = {"git ": "allow", "rm ": "deny"}
def decide(call):
    inner = call[5:-1]
    for prefix, verdict in RULES.items():
        if inner.startswith(prefix):
            return verdict
    return "ask"
for call in ("Bash(git status)", "Bash(rm -rf /)", "Bash(npm test)"):
    print(f"{call} -> {decide(call)}")

